// Safe fetch wrapper — converts CORS/network errors to identifiable messages
const safeFetch = async (url, opts) => {
  try {
    return await fetch(url, opts);
  } catch (err) {
    // Browser-side fetch failures (CORS, DNS, network) all surface as TypeError: Failed to fetch
    const e = new Error("Failed to fetch — provider blocks browser requests (CORS). Use a backend proxy or pick a model that supports browser calls (Claude works without one).");
    e.isNetwork = true;
    throw e;
  }
};

// Unified AI call — returns { text, toolUses, raw, stopReason, providerModel }
// Messages: [{role: "user"|"assistant", content: string | blockArray}]
// Blocks can include tool_use / tool_result for Claude-style multi-turn tool use.
const callModel = async ({ modelId, apiKey, systemPrompt, messages, tools, maxTokens = 1500 }) => {
  if (modelId === "claude") {
    const res = await safeFetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-20250514",
        max_tokens: maxTokens,
        system: systemPrompt,
        tools: tools || undefined,
        messages
      })
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      const e = new Error("HTTP " + res.status + (err ? ": " + err.slice(0, 160) : ""));
      e.status = res.status;
      throw e;
    }
    const data = await res.json();
    const content = data?.content || [];
    const text = content.filter(c => c.type === "text").map(c => c.text).join("\n").trim();
    const toolUses = content.filter(c => c.type === "tool_use");
    return { text, toolUses, raw: content, stopReason: data?.stop_reason, providerModel: "claude-sonnet-4" };
  }

  if (modelId === "openai") {
    // Flatten tool_use/result blocks to OpenAI format
    const oaMessages = [];
    if (systemPrompt) oaMessages.push({ role: "system", content: systemPrompt });
    for (const m of messages) {
      if (typeof m.content === "string") {
        oaMessages.push({ role: m.role, content: m.content });
      } else {
        // multi-block assistant message with tool_use
        const textParts = m.content.filter(c => c.type === "text").map(c => c.text).join("\n");
        const toolCalls = m.content.filter(c => c.type === "tool_use").map(c => ({ id: c.id, type: "function", function: { name: c.name, arguments: JSON.stringify(c.input || {}) } }));
        if (m.role === "assistant") {
          oaMessages.push({ role: "assistant", content: textParts || null, tool_calls: toolCalls.length ? toolCalls : undefined });
        } else {
          // user with tool_results
          m.content.forEach(c => {
            if (c.type === "tool_result") {
              oaMessages.push({ role: "tool", tool_call_id: c.tool_use_id, content: typeof c.content === "string" ? c.content : JSON.stringify(c.content) });
            } else if (c.type === "text") {
              oaMessages.push({ role: "user", content: c.text });
            }
          });
        }
      }
    }
    const oaTools = tools ? tools.map(t => ({ type: "function", function: { name: t.name, description: t.description, parameters: t.input_schema } })) : undefined;
    const res = await safeFetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + apiKey },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        max_tokens: maxTokens,
        messages: oaMessages,
        tools: oaTools
      })
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      const e = new Error("HTTP " + res.status + (err ? ": " + err.slice(0, 160) : ""));
      e.status = res.status;
      throw e;
    }
    const data = await res.json();
    const msg = data?.choices?.[0]?.message || {};
    const text = msg.content || "";
    const toolUses = (msg.tool_calls || []).map(tc => ({ type: "tool_use", id: tc.id, name: tc.function?.name, input: (() => { try { return JSON.parse(tc.function?.arguments || "{}"); } catch { return {}; } })() }));
    const rawBlocks = [];
    if (text) rawBlocks.push({ type: "text", text });
    toolUses.forEach(tu => rawBlocks.push(tu));
    return { text, toolUses, raw: rawBlocks, stopReason: toolUses.length ? "tool_use" : "stop", providerModel: "gpt-4o-mini" };
  }

  if (modelId === "gemini") {
    const contents = [];
    messages.forEach(m => {
      const parts = [];
      if (typeof m.content === "string") {
        parts.push({ text: m.content });
      } else {
        m.content.forEach(c => {
          if (c.type === "text") parts.push({ text: c.text });
          else if (c.type === "tool_use") parts.push({ functionCall: { name: c.name, args: c.input || {} } });
          else if (c.type === "tool_result") parts.push({ functionResponse: { name: c.name || "tool", response: { result: typeof c.content === "string" ? c.content : JSON.stringify(c.content) } } });
        });
      }
      contents.push({ role: m.role === "assistant" ? "model" : "user", parts });
    });
    const geminiTools = tools ? [{ functionDeclarations: tools.map(t => ({ name: t.name, description: t.description, parameters: t.input_schema })) }] : undefined;
    const res = await safeFetch("https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=" + encodeURIComponent(apiKey), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        systemInstruction: systemPrompt ? { parts: [{ text: systemPrompt }] } : undefined,
        contents,
        tools: geminiTools,
        generationConfig: { maxOutputTokens: maxTokens, temperature: 0.7 }
      })
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      const e = new Error("HTTP " + res.status + (err ? ": " + err.slice(0, 160) : ""));
      e.status = res.status;
      throw e;
    }
    const data = await res.json();
    const parts = data?.candidates?.[0]?.content?.parts || [];
    const text = parts.filter(p => p.text).map(p => p.text).join("\n").trim();
    const toolUses = parts.filter(p => p.functionCall).map(p => ({ type: "tool_use", id: "gemini-" + Math.random().toString(36).slice(2, 10), name: p.functionCall.name, input: p.functionCall.args || {} }));
    const rawBlocks = [];
    if (text) rawBlocks.push({ type: "text", text });
    toolUses.forEach(tu => rawBlocks.push(tu));
    return { text, toolUses, raw: rawBlocks, stopReason: toolUses.length ? "tool_use" : "stop", providerModel: "gemini-2.0-flash" };
  }

  if (modelId === "groq") {
    // Groq uses OpenAI-compatible API
    const oaMessages = [];
    if (systemPrompt) oaMessages.push({ role: "system", content: systemPrompt });
    for (const m of messages) {
      if (typeof m.content === "string") {
        oaMessages.push({ role: m.role, content: m.content });
      } else {
        const textParts = m.content.filter(c => c.type === "text").map(c => c.text).join("\n");
        const toolCalls = m.content.filter(c => c.type === "tool_use").map(c => ({ id: c.id, type: "function", function: { name: c.name, arguments: JSON.stringify(c.input || {}) } }));
        if (m.role === "assistant") {
          oaMessages.push({ role: "assistant", content: textParts || null, tool_calls: toolCalls.length ? toolCalls : undefined });
        } else {
          m.content.forEach(c => {
            if (c.type === "tool_result") oaMessages.push({ role: "tool", tool_call_id: c.tool_use_id, content: typeof c.content === "string" ? c.content : JSON.stringify(c.content) });
            else if (c.type === "text") oaMessages.push({ role: "user", content: c.text });
          });
        }
      }
    }
    const oaTools = tools ? tools.map(t => ({ type: "function", function: { name: t.name, description: t.description, parameters: t.input_schema } })) : undefined;
    const res = await safeFetch("https://api.groq.com/openai/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + apiKey },
      body: JSON.stringify({
        model: "llama-3.3-70b-versatile",
        max_tokens: maxTokens,
        messages: oaMessages,
        tools: oaTools
      })
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      const e = new Error("HTTP " + res.status + (err ? ": " + err.slice(0, 160) : ""));
      e.status = res.status;
      throw e;
    }
    const data = await res.json();
    const msg = data?.choices?.[0]?.message || {};
    const text = msg.content || "";
    const toolUses = (msg.tool_calls || []).map(tc => ({ type: "tool_use", id: tc.id, name: tc.function?.name, input: (() => { try { return JSON.parse(tc.function?.arguments || "{}"); } catch { return {}; } })() }));
    const rawBlocks = [];
    if (text) rawBlocks.push({ type: "text", text });
    toolUses.forEach(tu => rawBlocks.push(tu));
    return { text, toolUses, raw: rawBlocks, stopReason: toolUses.length ? "tool_use" : "stop", providerModel: "llama-3.3-70b" };
  }

  if (modelId === "mistral") {
    const oaMessages = [];
    if (systemPrompt) oaMessages.push({ role: "system", content: systemPrompt });
    for (const m of messages) {
      if (typeof m.content === "string") {
        oaMessages.push({ role: m.role, content: m.content });
      } else {
        const textParts = m.content.filter(c => c.type === "text").map(c => c.text).join("\n");
        const toolCalls = m.content.filter(c => c.type === "tool_use").map(c => ({ id: c.id, type: "function", function: { name: c.name, arguments: JSON.stringify(c.input || {}) } }));
        if (m.role === "assistant") {
          oaMessages.push({ role: "assistant", content: textParts || null, tool_calls: toolCalls.length ? toolCalls : undefined });
        } else {
          m.content.forEach(c => {
            if (c.type === "tool_result") oaMessages.push({ role: "tool", tool_call_id: c.tool_use_id, name: c.name || "tool", content: typeof c.content === "string" ? c.content : JSON.stringify(c.content) });
            else if (c.type === "text") oaMessages.push({ role: "user", content: c.text });
          });
        }
      }
    }
    const mTools = tools ? tools.map(t => ({ type: "function", function: { name: t.name, description: t.description, parameters: t.input_schema } })) : undefined;
    const res = await safeFetch("https://api.mistral.ai/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + apiKey },
      body: JSON.stringify({
        model: "mistral-large-latest",
        max_tokens: maxTokens,
        messages: oaMessages,
        tools: mTools
      })
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      const e = new Error("HTTP " + res.status + (err ? ": " + err.slice(0, 160) : ""));
      e.status = res.status;
      throw e;
    }
    const data = await res.json();
    const msg = data?.choices?.[0]?.message || {};
    const text = msg.content || "";
    const toolUses = (msg.tool_calls || []).map(tc => ({ type: "tool_use", id: tc.id, name: tc.function?.name, input: (() => { try { return JSON.parse(tc.function?.arguments || "{}"); } catch { return {}; } })() }));
    const rawBlocks = [];
    if (text) rawBlocks.push({ type: "text", text });
    toolUses.forEach(tu => rawBlocks.push(tu));
    return { text, toolUses, raw: rawBlocks, stopReason: toolUses.length ? "tool_use" : "stop", providerModel: "mistral-large" };
  }

  if (modelId === "minimax") {
    // MiniMax chatcompletion — plain text only (no tool use in this simplified adapter)
    const mmMessages = [];
    if (systemPrompt) mmMessages.push({ sender_type: "BOT", sender_name: "MM Assistant", text: systemPrompt });
    for (const m of messages) {
      const txt = typeof m.content === "string" ? m.content : m.content.filter(c => c.type === "text").map(c => c.text).join("\n");
      if (!txt) continue;
      mmMessages.push({ sender_type: m.role === "assistant" ? "BOT" : "USER", sender_name: m.role === "assistant" ? "MM Assistant" : "User", text: txt });
    }
    const res = await safeFetch("https://api.minimaxi.com/v1/text/chatcompletion_v2", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + apiKey },
      body: JSON.stringify({
        model: "abab6.5s-chat",
        tokens_to_generate: maxTokens,
        messages: mmMessages.map(m => ({ role: m.sender_type === "BOT" ? "assistant" : "user", content: m.text }))
      })
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      const e = new Error("HTTP " + res.status + (err ? ": " + err.slice(0, 160) : ""));
      e.status = res.status;
      throw e;
    }
    const data = await res.json();
    const text = data?.choices?.[0]?.message?.content || data?.reply || "";
    return { text, toolUses: [], raw: [{ type: "text", text }], stopReason: "stop", providerModel: "abab6.5s" };
  }

  throw new Error("Unknown model: " + modelId);
};

// ===== GOOGLE WORKSPACE API LAYER =====
// All Google calls go through the user's deployed backend proxy.
// Backend URL: settings.googleBackendUrl (e.g. https://smocks-google.railway.app)
// When not connected, functions return mock data with realistic shapes.

// Authenticated fetch through backend proxy
const googleFetch = async (backendUrl, token, endpoint, opts = {}) => {
  if (!backendUrl || !token) throw new Error("Google not connected. Set backend URL and token in Settings → Integrations.");
  const url = backendUrl.replace(/\/$/, "") + "/api/google" + endpoint;
  const res = await fetch(url, {
    ...opts,
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + token,
      ...(opts.headers || {})
    }
  });
  if (!res.ok) {
    const err = await res.text().catch(() => "");
    throw new Error("Google API " + res.status + (err ? ": " + err.slice(0, 200) : ""));
  }
  return res.json();
};

// Gmail — list inbox messages
// Backend endpoint: GET /api/google/gmail/messages?maxResults=20
const fetchGmailInbox = async (backendUrl, token, maxResults = 20) => {
  return googleFetch(backendUrl, token, `/gmail/messages?maxResults=${maxResults}`);
};

