const parseRateLimitError = (err, modelId) => {
  const msg = (err?.message || "").toLowerCase();
  const status = err?.status;

  // Network / CORS errors — happen when browser blocks the API call
  // These should trigger immediate failover to a different provider, but with shorter lockout (5 min)
  // because they might be transient
  const isNetworkError = msg.includes("failed to fetch") || msg.includes("network") || msg.includes("cors") || msg.includes("typeerror");
  if (isNetworkError) {
    return { lockedUntil: Date.now() + 5 * 60 * 1000, reason: "Network/CORS blocked", network: true };
  }

  // Anthropic artifact sandbox throttle ("Message rate limit exceeded. Reload to continue.")
  // This is a soft artifact-side limit, not a real Anthropic API limit. Lock for ~3 min.
  const isSandboxThrottle = msg.includes("message rate limit exceeded") || msg.includes("reload to continue");
  if (isSandboxThrottle) {
    return { lockedUntil: Date.now() + 3 * 60 * 1000, reason: "Artifact throttle (3 min)", sandbox: true };
  }

  // Standard rate-limit detection
  const isRateLimit = status === 429 || msg.includes("rate limit") || msg.includes("quota") || msg.includes("exceeded") || msg.includes("too many") || msg.includes("rate_limit");
  if (!isRateLimit) return null;

  // Try to extract retry-after / reset time from message
  const retryMatch = msg.match(/retry(?:-| )after[: ]+(\d+)/) || msg.match(/in (\d+) seconds/);
  const retrySec = retryMatch ? parseInt(retryMatch[1]) : null;
  const defaultWindow = MODELS[modelId]?.resetWindow || 3600000;
  const lockedUntil = Date.now() + (retrySec ? retrySec * 1000 : defaultWindow);
  return { lockedUntil, reason: "Rate limit" };
};

