// ===== PIPELINE SCROLL CONTAINER =====
// Handles horizontal scroll with visible scrollbar + touch swipe on mobile
function PipelineScrollContainer({ children }) {
  const ref = useRef(null);
  const isDragging = useRef(false);
  const startX = useRef(0);
  const scrollStart = useRef(0);

  // Mouse drag-to-scroll (desktop)
  const onMouseDown = e => {
    // Only scroll if clicking on the container bg, not on cards
    if (e.target.closest(".pipeline-card")) return;
    isDragging.current = true;
    startX.current = e.pageX - (ref.current?.offsetLeft || 0);
    scrollStart.current = ref.current?.scrollLeft || 0;
    ref.current.style.cursor = "grabbing";
    ref.current.style.userSelect = "none";
  };
  const onMouseMove = e => {
    if (!isDragging.current) return;
    const x = e.pageX - (ref.current?.offsetLeft || 0);
    const walk = (x - startX.current) * 1.5;
    if (ref.current) ref.current.scrollLeft = scrollStart.current - walk;
  };
  const onMouseUp = () => {
    isDragging.current = false;
    if (ref.current) { ref.current.style.cursor = ""; ref.current.style.userSelect = ""; }
  };

  return (
    <>
      <style>{`
        .pipeline-scroll::-webkit-scrollbar { height: 8px; }
        .pipeline-scroll::-webkit-scrollbar-track { background: rgba(127,29,29,0.15); border-radius: 4px; }
        .pipeline-scroll::-webkit-scrollbar-thumb { background: rgba(220,38,38,0.55); border-radius: 4px; border: 1px solid rgba(220,38,38,0.2); }
        .pipeline-scroll::-webkit-scrollbar-thumb:hover { background: rgba(220,38,38,0.8); }
        .pipeline-scroll { scrollbar-width: thick; scrollbar-color: rgba(220,38,38,0.55) rgba(127,29,29,0.15); }
      `}</style>
      <div
        ref={ref}
        className="pipeline-scroll overflow-x-auto pb-3 -mx-1"
        style={{ WebkitOverflowScrolling: "touch", touchAction: "pan-x" }}
        onMouseDown={onMouseDown}
        onMouseMove={onMouseMove}
        onMouseUp={onMouseUp}
        onMouseLeave={onMouseUp}
      >
        {children}
      </div>
    </>
  );
}

// Touch-swipeable pipeline card — wrap each card for swipe-to-move between stages
function SwipeableCard({ job, stages = [], onMove, children }) {
  const touchStartX = useRef(null);
  const touchStartY = useRef(null);
  const [swipeHint, setSwipeHint] = useState(null); // "left" | "right" | null

  const currentIdx = stages.findIndex(s => s.key === job.pipelineStage);

  const onTouchStart = e => {
    touchStartX.current = e.touches[0].clientX;
    touchStartY.current = e.touches[0].clientY;
    setSwipeHint(null);
  };

  const onTouchMove = e => {
    if (touchStartX.current === null) return;
    const dx = e.touches[0].clientX - touchStartX.current;
    const dy = Math.abs(e.touches[0].clientY - touchStartY.current);
    if (Math.abs(dx) > 20 && dy < 40) {
      setSwipeHint(dx > 0 ? "right" : "left");
    }
  };

  const onTouchEnd = e => {
    if (touchStartX.current === null) { setSwipeHint(null); return; }
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    const dy = Math.abs(e.changedTouches[0].clientY - touchStartY.current);
    touchStartX.current = null;
    touchStartY.current = null;
    setSwipeHint(null);

    // Only trigger stage move if horizontal swipe > 60px and not mostly vertical
    if (Math.abs(dx) < 60 || dy > 60) return;

    if (dx > 0 && currentIdx > 0) {
      // Swipe right → move to previous stage
      onMove(job.id, stages[currentIdx - 1].key);
    } else if (dx < 0 && currentIdx < stages.length - 1) {
      // Swipe left → move to next stage
      const nextStage = stages[currentIdx + 1];
      if (nextStage.key === "lost") return; // don't auto-move to lost via swipe
      onMove(job.id, nextStage.key);
    }
  };

  return (
    <div
      className="pipeline-card relative"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
      style={{
        transform: swipeHint === "left" ? "translateX(-6px)" : swipeHint === "right" ? "translateX(6px)" : "translateX(0)",
        transition: swipeHint ? "transform 0.1s ease" : "transform 0.2s ease",
      }}
    >
      {/* Swipe direction indicators */}
      {swipeHint === "right" && currentIdx > 0 && (
        <div className="absolute inset-0 rounded-xl bg-blue-500/15 border-2 border-blue-400/50 pointer-events-none z-10 flex items-center justify-start pl-2">
          <div className="text-[10px] text-blue-300 font-bold flex items-center gap-1 bg-blue-950/80 px-2 py-1 rounded-lg">
            <ChevronLeft size={12} />
            {stages[currentIdx - 1]?.label}
          </div>
        </div>
      )}
      {swipeHint === "left" && currentIdx < stages.length - 2 && (
        <div className="absolute inset-0 rounded-xl bg-green-500/15 border-2 border-green-400/50 pointer-events-none z-10 flex items-center justify-end pr-2">
          <div className="text-[10px] text-green-300 font-bold flex items-center gap-1 bg-green-950/80 px-2 py-1 rounded-lg">
            {stages[currentIdx + 1]?.label}
            <ChevronRight size={12} />
          </div>
        </div>
      )}
      {children}
    </div>
  );
}

function PipelinePage({ jobs = [], setJobs, customers = [], toast }) {
  const [dragId, setDragId] = useState(null);
  const [lostJob, setLostJob] = useState(null);
  const [lostReason, setLostReason] = useState("Price too high");
  const [priorityFilter, setPriorityFilter] = useState("all");
  const [timeframe, setTimeframe] = useState("all");
  const lostReasons = ["Price too high", "Went with competitor", "Changed mind", "No response", "Not qualified", "Other"];

  const moveStg = (jid, stg) => {
    if (stg === "lost") { setLostJob(jid); return; }
    setJobs(jobs.map(j => j.id === jid ? { ...j, pipelineStage: stg, stageChangedAt: today() } : j));
  };

  const confirmLost = () => {
    setJobs(jobs.map(j => j.id === lostJob ? { ...j, pipelineStage: "lost", stageChangedAt: today(), lostReason } : j));
    setLostJob(null);
    toast("Marked lost: " + lostReason);
  };

  // Apply timeframe filter based on stageChangedAt or scheduledDate
  const tfDays = TIMEFRAMES.find(t => t.key === timeframe)?.days || 99999;
  const cutoff = Date.now() - tfDays * 86400000;
  const inTimeframe = jobs.filter(j => {
    if (timeframe === "all") return true;
    const d = j.stageChangedAt || j.scheduledDate;
    return d && new Date(d).getTime() >= cutoff;
  });

  const filtered = priorityFilter === "all" ? inTimeframe : inTimeframe.filter(j => (j.priority || "normal") === priorityFilter);

  // Pipeline health — avg days in each stage within timeframe
  const avgDays = pipelineStages.map(stg => {
    const sj = filtered.filter(j => j.pipelineStage === stg.key);
    if (!sj.length) return { stage: stg.label, avg: 0, count: 0 };
    const days = sj.map(j => daysSince(j.stageChangedAt || j.scheduledDate));
    return { stage: stg.label, avg: Math.round(days.reduce((s, d) => s + d, 0) / days.length), count: sj.length };
  });
  const bottleneck = avgDays.reduce((b, s) => s.avg > b.avg ? s : b, { stage: "", avg: 0, count: 0 });
  const tfLabel = TIMEFRAMES.find(t => t.key === timeframe)?.label || "All";

  // Win rate in timeframe
  const closedJobs = filtered.filter(j => j.pipelineStage === "paid" || j.pipelineStage === "completed");
  const lostJobs = filtered.filter(j => j.pipelineStage === "lost");
  const winRate = (closedJobs.length + lostJobs.length) > 0 ? Math.round(closedJobs.length / (closedJobs.length + lostJobs.length) * 100) : null;

  return (
    <div className="space-y-4">
      {/* Controls row */}
      <div className="flex items-center gap-3 flex-wrap justify-between">
        <div className="flex items-center gap-3 flex-wrap">
          <TimeframeSelector value={timeframe} onChange={setTimeframe} options={["7d","30d","90d","6m","1y","all"]} />
          <div className="flex gap-1 items-center">
            <span className="text-xs text-white/40">Priority:</span>
            {["all", ...priorityLevels.map(p => p.key)].map(p => (
              <button key={p} onClick={() => setPriorityFilter(p)} className={"px-2.5 py-1 rounded-lg text-xs transition border capitalize " + (priorityFilter === p ? "bg-red-900/40 border-red-500/50 text-white" : "bg-black/40 border-red-900/30 text-white/60 hover:text-white")}>{p}</button>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-3 text-xs text-white/60">
          <span><span className="text-red-400 font-bold">{filtered.length}</span> jobs</span>
          <span><span className="text-red-400 font-bold">{fmt(filtered.reduce((s, j) => s + j.amount, 0))}</span> value</span>
          {winRate !== null && <span><span className="text-green-400 font-bold">{winRate}%</span> win rate</span>}
        </div>
      </div>

      {/* Bottleneck & health bar */}
      {bottleneck.avg >= 5 && (
        <Glass className="p-4 !bg-yellow-950/20 !border-yellow-700/40">
          <div className="flex items-start gap-3 flex-wrap">
            <div className="flex items-center gap-2">
              <AlertTriangle size={14} className="text-yellow-400 flex-shrink-0" />
              <div>
                <span className="text-yellow-300 font-semibold">Bottleneck ({tfLabel}):</span>
                <span className="text-yellow-200 ml-1">{bottleneck.stage}</span>
                <span className="text-yellow-400/80 ml-2 text-sm">avg {bottleneck.avg}d · {bottleneck.count} job{bottleneck.count !== 1 ? "s" : ""}</span>
              </div>
            </div>
            <div className="flex gap-2 ml-auto text-[10px]">
              {avgDays.filter(s => s.count > 0).map(s => (
                <div key={s.stage} className={"px-2 py-1 rounded-lg border " + (s.stage === bottleneck.stage ? "bg-yellow-950/40 border-yellow-700/50 text-yellow-300" : "bg-black/40 border-white/10 text-white/50")}>
                  {s.stage}: <span className="font-bold">{s.avg}d</span>
                </div>
              ))}
            </div>
          </div>
        </Glass>
      )}

      {/* Lead aging report */}
      {(() => {
        const staleThreshold = 14;
        const activeStages = ["lead","contacted","estimate_sent"];
        const stale = filtered.filter(j => activeStages.includes(j.pipelineStage) && daysSince(j.stageChangedAt || j.scheduledDate || j.createdAt) >= staleThreshold);
        if (stale.length === 0) return null;
        return (
          <Glass className="p-4 !bg-orange-950/20 !border-orange-700/40">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Clock size={14} className="text-orange-400" />
                <span className="text-orange-300 font-semibold text-sm">{stale.length} lead{stale.length !== 1 ? "s" : ""} with no activity in {staleThreshold}+ days</span>
              </div>
              <span className="text-[10px] text-orange-400/60">Lead Aging Report</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead><tr className="text-orange-400/60 border-b border-orange-700/30">
                  <th className="text-left pb-1.5">Address / Customer</th>
                  <th className="text-center pb-1.5">Stage</th>
                  <th className="text-right pb-1.5">Value</th>
                  <th className="text-right pb-1.5">Age</th>
                  <th className="text-right pb-1.5">Action</th>
                </tr></thead>
                <tbody>
                  {stale.map(j => {
                    const cu = customers.find(c => c.id === j.customerId);
                    const age = daysSince(j.stageChangedAt || j.scheduledDate || j.createdAt);
                    return <tr key={j.id} className="border-b border-orange-900/20 hover:bg-orange-950/10">
                      <td className="py-2"><div className="font-medium text-white/80">{j.address?.split(",")[0] || "Unknown"}</div>{cu && <div className="text-orange-300/60">{cu.firstName} {cu.lastName}</div>}</td>
                      <td className="py-2 text-center"><Badge tone="orange">{pipelineStages.find(s => s.key === j.pipelineStage)?.label || j.pipelineStage}</Badge></td>
                      <td className="py-2 text-right font-semibold text-white/80">{fmt(j.amount)}</td>
                      <td className="py-2 text-right"><span className={age >= 30 ? "text-red-400 font-bold" : "text-orange-300"}>{age}d</span></td>
                      <td className="py-2 text-right">
                        <button onClick={() => cu?.phone && (window.location.href = "sms:" + cu.phone.replace(/\D/g,""))} className="text-[10px] text-blue-400 hover:text-blue-300">Text</button>
                      </td>
                    </tr>;
                  })}
                </tbody>
              </table>
            </div>
            <div className="mt-2 text-[9px] text-orange-400/40">Leads aged 30+ days in red · Total at-risk value: {fmt(stale.reduce((s,j)=>s+j.amount,0))}</div>
          </Glass>
        );
      })()}

      <PipelineScrollContainer>
        <div className="flex gap-3 min-w-max px-1 pb-1">
          {pipelineStages.map(stg => {
            const sj = filtered.filter(j => j.pipelineStage === stg.key);
            const stgAvg = avgDays.find(a => a.stage === stg.label)?.avg || 0;
            return (
              <div key={stg.key} onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); if (dragId) moveStg(dragId, stg.key); setDragId(null); }} className={"w-72 flex-shrink-0 bg-black/30 border rounded-2xl " + stg.border}>
                <div className={"p-3 rounded-t-2xl border-b " + stg.border} style={{ background: "linear-gradient(to right, var(--tw-gradient-from), var(--tw-gradient-to))" }}>
                  <div className={"p-3 rounded-t-2xl border-b " + stg.border + " bg-black/40"}>
                    <div className="flex items-center gap-2 justify-between">
                      <div className="flex items-center gap-2">
                        <div className={"w-2 h-2 rounded-full " + stg.color} />
                        <span className={"font-semibold text-sm uppercase tracking-wider " + stg.text}>{stg.label}</span>
                      </div>
                      <span className={"text-xs px-2 py-0.5 rounded-full font-bold " + stg.color + "/20 " + stg.text}>{sj.length}</span>
                    </div>
                    <div className="flex items-center justify-between mt-1">
                      <div className="text-xs text-white/60">{fmt(sj.reduce((s, j) => s + j.amount, 0))}</div>
                      {stgAvg > 0 && <div className="text-[10px] text-white/40">avg {stgAvg}d</div>}
                    </div>
                  </div>
                </div>
                <div className="p-2 space-y-2 min-h-[200px]">
                  {sj.map(j => {
                    const cu = customers.find(c => c.id === j.customerId);
                    const prio = priorityLevels.find(p => p.key === (j.priority || "normal")) || priorityLevels[1];
                    return (
                      <SwipeableCard key={j.id} job={j} stages={pipelineStages} onMove={moveStg}>
                      <div draggable onDragStart={() => setDragId(j.id)} className={"p-3 bg-black/60 rounded-xl cursor-grab hover:border active:cursor-grabbing select-none border " + stg.border + " hover:" + stg.border}>
                        <div className="flex items-start gap-2">
                          <div className={"w-1 h-full min-h-[40px] rounded-full flex-shrink-0 " + prio.color} />
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-1 flex-wrap">
                              <span className="font-medium text-sm truncate">{cu?.firstName} {cu?.lastName}</span>
                              {j.priority && j.priority !== "normal" && <Badge tone={prio.tone}>{prio.label}</Badge>}
                            </div>
                            <div className="text-[11px] text-white/50 truncate">{j.address}</div>
                            {j.tags && j.tags.length > 0 && <div className="flex gap-1 mt-1 flex-wrap">{j.tags.slice(0, 2).map(t => <span key={t} className="text-[8px] px-1.5 py-0.5 rounded-full bg-white/10 text-white/70">{t}</span>)}</div>}
                            <div className="flex items-center justify-between mt-1">
                              <div className={"text-xs font-semibold " + stg.text}>{fmt(j.amount)}</div>
                              {j.lostReason && stg.key === "lost" && <span className="text-[9px] text-red-400">{j.lostReason}</span>}
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-1 mt-2 pt-2 border-t border-white/5">
                          <button onClick={() => cu?.phone && (window.location.href = "tel:" + cu.phone.replace(/\D/g, ""))} className="flex-1 p-1 rounded hover:bg-green-900/30 text-white/50 hover:text-green-400 flex items-center justify-center" title={"Call " + cu?.firstName}><Phone size={10} /></button>
                          <button onClick={() => cu?.phone && (window.location.href = "sms:" + cu.phone.replace(/\D/g, ""))} className="flex-1 p-1 rounded hover:bg-blue-900/30 text-white/50 hover:text-blue-400 flex items-center justify-center" title={"Text " + cu?.firstName}><MessageSquare size={10} /></button>
                          {stg.key === "lost" ? (
                            <button onClick={() => { moveStg(j.id, "contacted"); toast("Lead re-opened → Contacted"); }} className="flex-1 p-1 rounded hover:bg-green-900/30 text-white/50 hover:text-green-400 flex items-center justify-center text-[9px] font-semibold gap-0.5"><RefreshCw size={9} />Re-open</button>
                          ) : (
                            <button onClick={() => cu?.email && (window.location.href = "mailto:" + cu.email)} className="flex-1 p-1 rounded hover:bg-purple-900/30 text-white/50 hover:text-purple-400 flex items-center justify-center" title={"Email " + cu?.firstName}><Mail size={10} /></button>
                          )}
                        </div>
                      </div>
                      </SwipeableCard>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </PipelineScrollContainer>

      <Modal open={!!lostJob} onClose={() => setLostJob(null)} title="Why lost?">
        <div className="space-y-3">
          <GSel value={lostReason} onChange={e => setLostReason(e.target.value)}>
            {lostReasons.map(r => <option key={r} value={r} className="bg-black">{r}</option>)}
          </GSel>
          <div className="flex gap-2 justify-end">
            <GBtn variant="ghost" onClick={() => setLostJob(null)}>Cancel</GBtn>
            <GBtn variant="danger" onClick={confirmLost}>Mark Lost</GBtn>
          </div>
        </div>
      </Modal>
    </div>
  );
}

// ===== CALENDAR =====
function CalendarPage({ jobs = [], setJobs, customers = [], toast, settings = {} }) {
  const [view, setView] = useState("month");
  const [off, setOff] = useState(0);
  const [dragId, setDragId] = useState(null);
  const [showBuffer, setShowBuffer] = useState(false); // show 30-min travel/buffer blocks

  const now = new Date();
  const vd = new Date(now.getFullYear(), now.getMonth() + off, 1);
  const y = vd.getFullYear();
  const m = vd.getMonth();
  const fd = new Date(y, m, 1).getDay();
  const dim = new Date(y, m + 1, 0).getDate();
  const byDate = {};
  jobs.forEach(j => { if (j.scheduledDate) (byDate[j.scheduledDate] = byDate[j.scheduledDate] || []).push(j); });
  const key = d => y + "-" + String(m + 1).padStart(2, "0") + "-" + String(d).padStart(2, "0");
  const tKey = today();

  const sColor = s => ({ scheduled: "bg-blue-600", in_progress: "bg-orange-500", completed: "bg-green-600", cancelled: "bg-red-800" }[s] || "bg-gray-600");
  const prioRing = p => ({ urgent: "ring-2 ring-red-500", high: "ring-2 ring-yellow-500", low: "opacity-75" }[p] || "");

  // Jobs without a scheduled date (for the "unscheduled" pool)
  const unscheduled = jobs.filter(j => !j.scheduledDate && j.status !== "completed" && j.status !== "cancelled");

  const handleDrop = async targetKey => {
    if (!dragId) return;
    const job = jobs.find(j => j.id === dragId);
    const oldDate = job?.scheduledDate;
    setJobs(jobs.map(j => j.id === dragId ? { ...j, scheduledDate: targetKey } : j));
    toast("Rescheduled to " + targetKey);
    setDragId(null);

    // Send reschedule notification to customer
    if (job && oldDate && oldDate !== targetKey) {
      const c = customers.find(x => x.id === job.customerId);
      if (c?.phone && settings?.twilioSid) {
        const msg = "Hi " + c.firstName + "! Your Smock's service has been rescheduled from " + oldDate + " to " + targetKey + ". Questions? Call (717) 555-0100. — Smock's";
        twilioSend(settings, c.phone, msg).catch(() => {});
      }
      // Update Google Calendar event if connected
      if (job.googleEventId && settings?.googleConnected && settings?.googleBackendUrl && settings?.googleToken) {
        fetch(settings.googleBackendUrl + "/calendar/events/" + job.googleEventId, {
          method: "PATCH",
          headers: { "Content-Type": "application/json", "Authorization": "Bearer " + settings.googleToken },
          body: JSON.stringify({ start: { date: targetKey }, end: { date: targetKey } })
        }).catch(() => {});
      }
    }
  };
  const unschedule = jid => {
    setJobs(jobs.map(j => j.id === jid ? { ...j, scheduledDate: "" } : j));
    toast("Moved to unscheduled");
  };

  // Day revenue totals
  const dayTotal = k => (byDate[k] || []).reduce((s, j) => s + (j.amount || 0), 0);

  // Week view calc
  const weekStart = new Date(now); weekStart.setDate(now.getDate() - now.getDay() + off * 7);
  const weekDays = Array.from({ length: 7 }).map((_, i) => { const d = new Date(weekStart); d.setDate(weekStart.getDate() + i); return d; });

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2 flex-wrap">
        {["month", "week", "agenda"].map(v => <button key={v} onClick={() => { setView(v); setOff(0); }} className={"px-4 py-2 rounded-xl text-sm font-medium transition border capitalize " + (view === v ? "bg-gradient-to-r from-red-600 to-red-800 border-red-500/50 text-white" : "bg-black/40 border-red-900/30 text-white/60 hover:text-white")}>{v}</button>)}
        <label className="flex items-center gap-2 ml-auto cursor-pointer px-3 py-2 bg-black/40 border border-red-900/30 rounded-xl text-xs text-white/60 hover:text-white transition">
          <input type="checkbox" checked={showBuffer} onChange={e => setShowBuffer(e.target.checked)} className="w-3.5 h-3.5 accent-red-500" />
          🚗 30-min travel buffers
        </label>
      </div>

      {view === "month" && (
        <div className="grid lg:grid-cols-[1fr_220px] gap-4">
          <Glass className="p-4">
          <div className="flex items-center justify-between mb-4">
            <button onClick={() => setOff(off - 1)} className="p-2 rounded-lg hover:bg-white/5"><ChevronLeft size={16} /></button>
            <div className="font-semibold">{vd.toLocaleString("default", { month: "long", year: "numeric" })}</div>
            <button onClick={() => setOff(off + 1)} className="p-2 rounded-lg hover:bg-white/5"><ChevronRight size={16} /></button>
          </div>
          <div className="grid grid-cols-7 gap-1 mb-2">{["S", "M", "T", "W", "T", "F", "S"].map((d, i) => <div key={i} className="text-center text-[10px] uppercase text-white/40 py-2">{d}</div>)}</div>
          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: fd }).map((_, i) => <div key={"p" + i} />)}
            {Array.from({ length: dim }).map((_, i) => {
              const d = i + 1;
              const k = key(d);
              const dj = byDate[k] || [];
              const isT = k === tKey;
              const dt = dayTotal(k);
              const hasCompleted = dj.some(j => j.status === "completed");
              const hasInProgress = dj.some(j => j.status === "in_progress");
              const hasUrgent = dj.some(j => j.priority === "urgent");
              const cellBg = isT ? "bg-red-950/30 border-red-700/50" : hasInProgress ? "bg-orange-950/20 border-orange-700/30" : hasCompleted && dj.every(j => j.status === "completed") ? "bg-green-950/20 border-green-800/30" : hasUrgent ? "bg-red-950/20 border-red-700/40" : dj.length > 0 ? "bg-blue-950/10 border-blue-900/20" : "bg-white/5 border-white/5 hover:border-red-900/30";
              return (
                <div key={d} onDragOver={e => e.preventDefault()} onDrop={() => handleDrop(k)} className={"min-h-[84px] p-1.5 rounded-lg border transition-all " + cellBg}>
                  <div className="flex items-center justify-between mb-1">
                    <div className={"text-xs font-semibold " + (isT ? "text-red-400" : "text-white/70")}>{d}</div>
                    {dt > 0 && <div className="text-[8px] text-green-400/70 font-mono">${Math.round(dt)}</div>}
                  </div>
                  <div className="space-y-0.5">
                    {dj.slice(0, 3).map(j => {
                      const c = customers.find(x => x.id === j.customerId);
                      return <React.Fragment key={j.id}>
                        {showBuffer && <div className="text-[8px] px-1 py-0.5 rounded bg-orange-950/50 border border-orange-800/30 text-orange-400/60 truncate">🚗 travel</div>}
                        <div draggable onDragStart={() => setDragId(j.id)} className={"text-[9px] px-1 py-0.5 rounded truncate cursor-grab text-white " + sColor(j.status) + " " + prioRing(j.priority)} title={c?.firstName + " " + c?.lastName + " · " + fmt(j.amount) + (j.priority && j.priority !== "normal" ? " · " + j.priority : "")}>{j.priority === "urgent" && "🚨 "}{c?.firstName}</div>
                        {showBuffer && <div className="text-[8px] px-1 py-0.5 rounded bg-gray-950/50 border border-gray-800/30 text-gray-400/60 truncate">⏸ buffer</div>}
                      </React.Fragment>;
                    })}
                    {dj.length > 3 && <div className="text-[9px] text-white/50">+{dj.length - 3}</div>}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="mt-3 flex items-center justify-center gap-3 flex-wrap text-[10px] text-white/50">
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-blue-600" />Scheduled</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-orange-500" />In progress</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-green-600" />Done</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-red-800" />Cancelled</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-blue-600 ring-2 ring-yellow-500" />High/Urgent</span>
          </div>
          </Glass>
          <Glass className="p-4 h-fit sticky top-24">
            <div className="text-xs text-white/50 uppercase tracking-wider mb-3 flex items-center gap-1.5"><Clipboard size={10} />Unscheduled ({unscheduled.length})</div>
            <div className="space-y-2 max-h-[500px] overflow-y-auto">
              {unscheduled.length === 0 && <div className="text-xs text-white/30 text-center py-6">Everything's on the board ✓</div>}
              {unscheduled.map(j => {
                const c = customers.find(x => x.id === j.customerId);
                return <div key={j.id} draggable onDragStart={() => setDragId(j.id)} className={"p-2.5 rounded-lg cursor-grab bg-black/40 border hover:border-red-600/50 transition " + (j.priority === "urgent" ? "border-red-500/50" : j.priority === "high" ? "border-yellow-500/50" : "border-red-900/30")}>
                  <div className="flex items-center justify-between gap-1 mb-1">
                    <div className="font-medium text-xs truncate">{c?.firstName} {c?.lastName}</div>
                    {j.priority && j.priority !== "normal" && <span className={"text-[8px] px-1 rounded uppercase " + (j.priority === "urgent" ? "bg-red-600/40 text-red-300" : j.priority === "high" ? "bg-yellow-600/40 text-yellow-300" : "bg-white/10 text-white/50")}>{j.priority[0]}</span>}
                  </div>
                  <div className="text-[10px] text-white/50 truncate">{j.address}</div>
                  <div className="text-[10px] text-red-400 font-semibold mt-0.5">{fmt(j.amount)}</div>
                </div>;
              })}
            </div>
            <div className="text-[9px] text-white/30 text-center mt-3 pt-3 border-t border-red-900/20">↳ Drag onto calendar to schedule</div>
            {jobs.some(j => j.scheduledDate) && <div className="mt-2 text-[9px] text-white/30 text-center">Drop on this panel to unschedule</div>}
            <div onDragOver={e => e.preventDefault()} onDrop={() => dragId && unschedule(dragId)} className="mt-2 h-8 border border-dashed border-white/10 rounded-lg flex items-center justify-center text-[9px] text-white/30">Drop here</div>
          </Glass>
        </div>
      )}

      {view === "week" && (
        <Glass className="p-4">
          <div className="flex items-center justify-between mb-4">
            <button onClick={() => setOff(off - 1)} className="p-2 rounded-lg hover:bg-white/5"><ChevronLeft size={16} /></button>
            <div className="font-semibold">{weekStart.toLocaleDateString()} week</div>
            <button onClick={() => setOff(off + 1)} className="p-2 rounded-lg hover:bg-white/5"><ChevronRight size={16} /></button>
          </div>
          <div className="grid grid-cols-7 gap-2">
            {weekDays.map(d => {
              const k = d.toISOString().slice(0, 10);
              const dj = byDate[k] || [];
              const isT = k === tKey;
              return (
                <div key={k} onDragOver={e => e.preventDefault()} onDrop={() => handleDrop(k)} className={"min-h-[200px] p-2 rounded-lg border " + (isT ? "bg-red-950/30 border-red-700/50" : "bg-white/5 border-white/10")}>
                  <div className={"text-[10px] uppercase " + (isT ? "text-red-400 font-bold" : "text-white/50")}>{d.toLocaleDateString("en-US", { weekday: "short" })}</div>
                  <div className="text-lg font-bold mb-2">{d.getDate()}</div>
                  <div className="space-y-1">
                    {dj.map(j => {
                      const c = customers.find(x => x.id === j.customerId);
                      return <div key={j.id} draggable onDragStart={() => setDragId(j.id)} className={"text-[10px] p-1.5 rounded cursor-grab " + sColor(j.status) + " text-white"}>
                        <div className="font-semibold truncate">{c?.firstName}</div>
                        <div className="opacity-75">{fmt(j.amount)}</div>
                      </div>;
                    })}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="mt-3 text-[10px] text-white/40 text-center">Buffer time: 30min between jobs (mock)</div>
        </Glass>
      )}

      {view === "agenda" && (
        <Glass className="p-4">
          <div className="space-y-2">
            {jobs.filter(j => j.scheduledDate >= tKey && j.status !== "cancelled").sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate)).slice(0, 20).map(j => {
              const c = customers.find(x => x.id === j.customerId);
              return (
                <div key={j.id} className="flex items-center gap-3 p-3 bg-white/5 border border-white/5 rounded-xl">
                  <div className={"w-1 h-10 rounded-full " + sColor(j.status)} />
                  <div className="flex-1 min-w-0">
                    <div className="font-medium text-sm">{c?.firstName} {c?.lastName}</div>
                    <div className="text-xs text-white/50 truncate">{j.address}</div>
                  </div>
                  <div className="text-right">
                    <div className="font-semibold text-red-400 text-sm">{fmt(j.amount)}</div>
                    <div className="text-xs text-white/50">{j.scheduledDate}</div>
                  </div>
                </div>
              );
            })}
          </div>
        </Glass>
      )}
    </div>
  );
}

// ===== REVIEWS =====
function ReviewMonitor({ settings = {}, toast }) {
  const [newR, setNewR] = useState({ reviewer: "", rating: 5, text: "", date: today(), source: "Google" });
  const [loggedReviews, setLoggedReviews] = usePersistent("smocks.googleReviews", []);

  const avg = loggedReviews.length ? loggedReviews.reduce((s,r) => s + r.rating, 0) / loggedReviews.length : 0;

  return (
    <div className="space-y-4">
      <Glass className="p-5 !bg-gradient-to-br !from-blue-950/20 !to-black/60 !border-blue-700/30">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2"><span className="text-xl">🔍</span><h3 className="font-semibold">Google Review Monitoring</h3></div>
          {loggedReviews.length > 0 && <div className="text-yellow-400 font-bold text-sm">★ {avg.toFixed(1)} avg · {loggedReviews.length} logged</div>}
        </div>
        <div className="text-xs text-white/60 mt-1">Manually log reviews from Google to track trends. Add your Place ID in Settings → Company for direct links.</div>
      </Glass>

      <div className="grid md:grid-cols-2 gap-4">
        <Glass className="p-4 space-y-3">
          <div className="font-semibold text-sm">Quick Links</div>
          {settings.googlePlaceId ? <>
            <a href={"https://search.google.com/local/reviews?placeid=" + settings.googlePlaceId} target="_blank" rel="noopener noreferrer" className="w-full flex items-center gap-2 py-2.5 bg-blue-950/30 border border-blue-700/40 text-blue-300 rounded-xl hover:bg-blue-900/40 transition text-xs font-medium px-3"><ExternalLink size={12} />Open Google Reviews</a>
            <a href={"https://www.google.com/maps/search/?api=1&query=smocks+pressure+washing&query_place_id=" + settings.googlePlaceId} target="_blank" rel="noopener noreferrer" className="w-full flex items-center gap-2 py-2.5 bg-black/40 border border-white/10 text-white/60 rounded-xl hover:text-white transition text-xs px-3"><ExternalLink size={12} />View on Google Maps</a>
            <button onClick={() => { navigator.clipboard?.writeText("https://search.google.com/local/reviews?placeid=" + settings.googlePlaceId); toast("Review link copied ✓"); }} className="w-full flex items-center gap-2 py-2 bg-black/40 border border-white/10 text-white/50 rounded-xl hover:text-white transition text-xs px-3"><Link size={12} />Copy review request link</button>
          </> : <div className="text-xs text-yellow-400 p-3 bg-yellow-950/20 border border-yellow-700/30 rounded-xl">Add your Google Place ID in Settings → Company → Google Place ID to enable monitoring links.</div>}
          <div className="text-[10px] text-white/30 pt-2 border-t border-white/5">Best practice: respond to every Google review within 24 hours for maximum ranking signals.</div>
        </Glass>

        <Glass className="p-4 space-y-3">
          <div className="font-semibold text-sm">Log a Google Review</div>
          <div className="text-[10px] text-white/50">Found a new review? Log it here to track your rating trends over time.</div>
          <GInput value={newR.reviewer} onChange={e => setNewR(p => ({ ...p, reviewer: e.target.value }))} placeholder="Reviewer name" className="!text-xs" />
          <div className="flex items-center gap-3">
            <label className="text-[10px] text-white/50">Rating:</label>
            <div className="flex gap-0.5">{[1,2,3,4,5].map(n => <button key={n} onClick={() => setNewR(p => ({ ...p, rating: n }))} className={"text-xl transition " + (newR.rating >= n ? "text-yellow-400" : "text-white/20")}>★</button>)}</div>
          </div>
          <GTxt rows={2} value={newR.text} onChange={e => setNewR(p => ({ ...p, text: e.target.value }))} placeholder="Review text (optional)..." className="!text-xs" />
          <GDate value={newR.date} onChange={e => setNewR(p => ({ ...p, date: e.target.value }))} className="!text-xs !py-1.5" />
          <GBtn onClick={() => {
            if (!newR.reviewer.trim()) return;
            setLoggedReviews(prev => [{ ...newR, id: uid() }, ...prev]);
            setNewR({ reviewer: "", rating: 5, text: "", date: today(), source: "Google" });
            toast("Review logged ✓");
          }} disabled={!newR.reviewer.trim()} className="w-full !text-xs">Log Review</GBtn>
        </Glass>
      </div>

      {loggedReviews.length > 0 && <Glass className="p-4">
        <div className="flex items-center justify-between mb-3">
          <div className="font-semibold text-sm">Review Log ({loggedReviews.length})</div>
          <div className="flex gap-3 text-xs text-white/50">
            <span className="text-green-400">{loggedReviews.filter(r => r.rating >= 4).length} positive</span>
            <span className="text-red-400">{loggedReviews.filter(r => r.rating <= 3).length} negative</span>
          </div>
        </div>
        <div className="space-y-2 max-h-80 overflow-y-auto">
          {loggedReviews.map(r => (
            <div key={r.id} className={"p-3 border rounded-xl text-xs " + (r.rating >= 4 ? "bg-green-950/10 border-green-900/30" : "bg-red-950/10 border-red-900/30")}>
              <div className="flex items-center justify-between mb-1">
                <span className="font-semibold">{r.reviewer}</span>
                <div className="flex items-center gap-2">
                  <span className="text-yellow-400">{"★".repeat(r.rating)}{"☆".repeat(5-r.rating)}</span>
                  <span className="text-white/40">{r.date}</span>
                  <button onClick={() => setLoggedReviews(prev => prev.filter(x => x.id !== r.id))} className="text-white/20 hover:text-red-400"><X size={10} /></button>
                </div>
              </div>
              {r.text && <div className="text-white/60 italic">"{r.text}"</div>}
            </div>
          ))}
        </div>
      </Glass>}
    </div>
  );
}

function ReviewsPage({ reviews = [], setReviews, jobs = [], customers = [], toast, negativeAlerts = [], setNegativeAlerts, settings = {}, setSettings }) {
  const [preview, setPreview] = useState(null);
  const [landingReview, setLandingReview] = useState(null);
  const [tab, setTab] = useState("inbox");

  const cf = jid => { const j = jobs.find(x => x.id === jid); return j ? customers.find(c => c.id === j.customerId) : null; };
  const jf = jid => jobs.find(x => x.id === jid);

  // 90-day throttling check
  const canSend = rid => {
    const r = reviews.find(x => x.id === rid);
    if (!r) return false;
    const c = cf(r.jobId);
    if (!c) return false;
    const recentSent = reviews.filter(x => {
      const xj = jf(x.jobId);
      return xj && xj.customerId === c.id && x.sentAt && daysSince(x.sentAt) < 90 && x.id !== rid;
    });
    return recentSent.length === 0;
  };

  const sendReq = async rid => {
    if (!canSend(rid)) { toast("Throttled — review request sent within last 90 days", "error"); return; }
    const r = reviews.find(x => x.id === rid);
    const c = cf(r?.jobId);
    if (!c) return;
    if ((settings.unsubscribedEmails || []).includes(c.email)) { toast("Customer has unsubscribed from review requests"); return; }
    if ((settings.reviewUnsubscribedPhones || []).includes(c.phone)) { toast("Customer opted out of SMS review requests"); return; }

    // Build review URL with token
    const reviewUrl = "smocks.com/r/" + r.token;
    const unsubUrl = "smocks.com/unsub/" + btoa(c.phone || c.email || c.id).slice(0, 12);
    const msg = "Hi " + c.firstName + "! Thanks for choosing Smock's Pressure Washing 🙌 How'd we do? Leave us a quick review — it means the world to a small business: " + reviewUrl + "\n\nReply STOP to opt out.";

    let sent = false;
    if (settings?.twilioSid && c.phone) {
      try { await twilioSend(settings, c.phone, msg); sent = true; toast("Review request sent to " + c.firstName + " via SMS ✓"); }
      catch(e) { toast("SMS failed: " + e.message, "error"); }
    } else if (c.phone) {
      window.location.href = "sms:" + c.phone.replace(/\D/g,"") + "?body=" + encodeURIComponent(msg);
      sent = true;
    }
    if (sent) {
      setReviews(reviews.map(x => x.id === rid ? { ...x, status: "sent", sentAt: today() } : x));
    }
    setPreview(r);
  };

  const unsubscribe = (identifier, type = "email") => {
    if (type === "phone") {
      setSettings({ ...settings, reviewUnsubscribedPhones: [...(settings.reviewUnsubscribedPhones || []), identifier] });
    } else {
      setSettings({ ...settings, unsubscribedEmails: [...(settings.unsubscribedEmails || []), identifier] });
    }
    toast("Unsubscribed — they won't receive review requests");
  };

  const updRev = (rid, u) => setReviews(reviews.map(r => r.id === rid ? { ...r, ...u } : r));

  const subRev = (rid, rating) => {
    setReviews(reviews.map(r => r.id === rid ? { ...r, status: "completed" } : r));
    if (rating > 0 && rating <= 3) {
      const r = reviews.find(x => x.id === rid);
      const c = cf(r.jobId);
      setNegativeAlerts(prev => [...prev, { id: uid(), reviewId: rid, customerName: c ? c.firstName + " " + c.lastName : "?", rating, at: today() }]);
      toast("Negative feedback flagged", "error");
    } else if (rating >= 4) {
      toast("Great! Would redirect to Google Reviews");
    }
    setPreview(null);
  };

  const dismissAlert = id => setNegativeAlerts(negativeAlerts.filter(a => a.id !== id));
  const createFollowUp = a => {
    // Auto-create a follow-up note/reminder
    toast("Follow-up task created for " + a.customerName + " — check Tasks");
    dismissAlert(a.id);
  };

  const completed = reviews.filter(r => r.status === "completed" && r.rating > 0);
  const avg = completed.length ? (completed.reduce((s, r) => s + r.rating, 0) / completed.length).toFixed(1) : "—";
  const responseRate = reviews.filter(r => r.status === "sent").length > 0
    ? Math.round(completed.length / reviews.filter(r => r.status !== "pending").length * 100)
    : 0;
  const byRating = [5,4,3,2,1].map(n => ({ n, count: completed.filter(r => r.rating === n).length }));

  return (
    <div className="space-y-4">
      {negativeAlerts.length > 0 && (
        <Glass className="p-4 !bg-red-950/30 !border-red-600/50">
          <div className="flex items-center gap-2 mb-3"><AlertTriangle size={16} className="text-red-400" /><h3 className="font-semibold text-red-300 text-sm">Negative Feedback — Action Required</h3></div>
          <div className="space-y-2">
            {negativeAlerts.map(a => (
              <div key={a.id} className="flex items-center gap-3 p-2.5 bg-black/40 rounded-xl">
                <div className="flex gap-0.5">{Array.from({ length: 5 }).map((_, i) => <Star key={i} size={10} className={i < a.rating ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}</div>
                <span className="text-sm flex-1">{a.customerName}</span>
                <button onClick={() => createFollowUp(a)} className="px-2.5 py-1 text-[10px] bg-blue-950/40 border border-blue-700/40 text-blue-300 rounded-lg hover:bg-blue-900/50">📋 Create Task</button>
                {a.customerPhone && <button onClick={() => window.location.href = "tel:" + a.customerPhone.replace(/\D/g,"")} className="px-2.5 py-1 text-[10px] bg-green-950/40 border border-green-700/40 text-green-300 rounded-lg hover:bg-green-900/50">📞 Call</button>}
                <button onClick={() => dismissAlert(a.id)} className="p-1 text-white/40 hover:text-white"><X size={12} /></button>
              </div>
            ))}
          </div>
        </Glass>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <Stat icon={Clock} label="Pending" value={reviews.filter(r => r.status === "pending").length} />
        <Stat icon={Send} label="Sent" value={reviews.filter(r => r.status === "sent").length} />
        <Stat icon={CheckCircle} label="Completed" value={completed.length} />
        <Stat icon={Star} label="Avg Rating" value={avg} />
      </div>

      <div className="flex gap-2 flex-wrap">
        {[{ k: "inbox", l: "Inbox", n: reviews.length }, { k: "showcase", l: "Showcase Wall", n: completed.filter(r => r.rating >= (settings.reviewShowcaseMinRating || 5)).length }, { k: "monitor", l: "🔍 Monitor" }, { k: "analytics", l: "📊 Analytics" }].map(t => (
          <button key={t.k} onClick={() => setTab(t.k)} className={"px-4 py-2 rounded-xl text-sm font-medium transition border " + (tab === t.k ? "bg-gradient-to-r from-red-600 to-red-800 text-white border-red-500/50" : "bg-black/40 text-white/60 hover:text-white border-red-900/30")}>{t.l}{t.n !== undefined ? " (" + t.n + ")" : ""}</button>
        ))}
      </div>

      {tab === "monitor" && <ReviewMonitor settings={settings} toast={toast} />}

      {tab === "analytics" && <div className="space-y-4">
        <div className="grid md:grid-cols-3 gap-4">
          <Glass className="p-5">
            <div className="text-center mb-4">
              <div className="text-5xl font-black text-yellow-400">{avg}</div>
              <div className="text-xs text-white/50 mt-1">Average Rating · {completed.length} reviews</div>
              <div className="flex justify-center gap-0.5 mt-2">
                {[1,2,3,4,5].map(s => <Star key={s} size={16} className={s <= Math.round(Number(avg)) ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}
              </div>
            </div>
            <div className="space-y-1.5">
              {byRating.map(({ n, count }) => <div key={n} className="flex items-center gap-2">
                <span className="text-xs text-white/60 w-4">{n}★</span>
                <div className="flex-1 h-2 bg-black/40 rounded-full overflow-hidden">
                  <div className="h-full bg-yellow-400 rounded-full" style={{ width: completed.length > 0 ? (count/completed.length*100) + "%" : "0%" }} />
                </div>
                <span className="text-xs text-white/50 w-6 text-right">{count}</span>
              </div>)}
            </div>
          </Glass>
          <Glass className="p-5">
            <div className="text-xs text-white/50 uppercase tracking-wider mb-4">Response Metrics</div>
            <div className="space-y-4">
              <div>
                <div className="flex justify-between text-xs mb-1"><span className="text-white/70">Response Rate</span><span className="font-bold text-green-400">{responseRate}%</span></div>
                <div className="h-2 bg-black/40 rounded-full overflow-hidden"><div className="h-full bg-green-500 rounded-full" style={{ width: responseRate + "%" }} /></div>
              </div>
              <div>
                <div className="flex justify-between text-xs mb-1"><span className="text-white/70">5-Star Rate</span><span className="font-bold text-yellow-400">{completed.length > 0 ? Math.round(completed.filter(r => r.rating === 5).length/completed.length*100) : 0}%</span></div>
                <div className="h-2 bg-black/40 rounded-full overflow-hidden"><div className="h-full bg-yellow-400 rounded-full" style={{ width: completed.length > 0 ? (completed.filter(r => r.rating === 5).length/completed.length*100) + "%" : "0%" }} /></div>
              </div>
              <div>
                <div className="flex justify-between text-xs mb-1"><span className="text-white/70">Negative Rate</span><span className="font-bold text-red-400">{completed.length > 0 ? Math.round(completed.filter(r => r.rating <= 3).length/completed.length*100) : 0}%</span></div>
                <div className="h-2 bg-black/40 rounded-full overflow-hidden"><div className="h-full bg-red-500 rounded-full" style={{ width: completed.length > 0 ? (completed.filter(r => r.rating <= 3).length/completed.length*100) + "%" : "0%" }} /></div>
              </div>
              <div className="pt-2 border-t border-red-900/20 text-xs text-white/50">
                <div className="flex justify-between"><span>Sent</span><span>{reviews.filter(r => r.sentAt).length}</span></div>
                <div className="flex justify-between mt-1"><span>90-day throttle</span><span>active ✓</span></div>
              </div>
            </div>
          </Glass>
          <Glass className="p-5">
            <div className="text-xs text-white/50 uppercase tracking-wider mb-4">Recent Reviews</div>
            <div className="space-y-3">
              {completed.slice(0, 5).map(r => {
                const c = cf(r.jobId);
                return <div key={r.id} className="flex items-start gap-2">
                  <div className="flex gap-0.5 flex-shrink-0 mt-0.5">{[1,2,3,4,5].map(s => <Star key={s} size={9} className={s <= r.rating ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}</div>
                  <div className="flex-1 min-w-0">
                    <div className="text-xs font-medium truncate">{c?.firstName} {c?.lastName}</div>
                    {r.feedback && <div className="text-[10px] text-white/50 truncate italic">"{r.feedback}"</div>}
                  </div>
                </div>;
              })}
              {completed.length === 0 && <div className="text-xs text-white/40 text-center py-4">No reviews yet</div>}
            </div>
          </Glass>
        </div>

        {/* Google Review Monitoring */}
        <Glass className="p-5">
          <h3 className="font-semibold mb-3 flex items-center gap-2"><Globe size={14} className="text-blue-400" />Google Review Monitoring</h3>
          <div className="text-xs text-white/60 mb-4">Manual check — paste your Google Place ID to open your review panel, or set up a webhook for real-time monitoring.</div>
          <div className="grid md:grid-cols-2 gap-4">
            <div>
              <div className="text-[10px] text-white/50 uppercase tracking-wider mb-2">Quick Actions</div>
              <div className="space-y-2">
                <a href={settings?.googlePlaceId ? "https://business.google.com/reviews" : "https://business.google.com"} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 p-3 bg-black/40 border border-blue-900/20 rounded-xl text-xs hover:border-blue-600/50 transition">
                  <span className="text-xl">🔍</span>
                  <div><div className="font-medium">Check Google Reviews</div><div className="text-white/50">Opens Google Business dashboard</div></div>
                  <ExternalLink size={10} className="ml-auto text-white/40" />
                </a>
                <a href={settings?.googlePlaceId ? "https://search.google.com/local/writereview?placeid=" + settings.googlePlaceId : "#"} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 p-3 bg-black/40 border border-yellow-900/20 rounded-xl text-xs hover:border-yellow-600/50 transition">
                  <span className="text-xl">⭐</span>
                  <div><div className="font-medium">Your Review Link</div><div className="text-white/50">{settings?.googlePlaceId ? "Place ID set ✓ — link ready" : "Set Google Place ID in Settings → Company"}</div></div>
                  <ExternalLink size={10} className="ml-auto text-white/40" />
                </a>
              </div>
            </div>
            <div>
              <div className="text-[10px] text-white/50 uppercase tracking-wider mb-2">Response Rate Goals</div>
              <div className="space-y-2 text-xs">
                <div className="flex justify-between p-2.5 bg-black/40 rounded-lg"><span className="text-white/70">Target response time</span><span className="font-semibold">24 hours</span></div>
                <div className="flex justify-between p-2.5 bg-black/40 rounded-lg"><span className="text-white/70">Negative review SLA</span><span className="font-semibold text-red-400">2 hours</span></div>
                <div className="flex justify-between p-2.5 bg-black/40 rounded-lg"><span className="text-white/70">Min rating to respond</span><span className="font-semibold">All reviews</span></div>
                <div className="flex justify-between p-2.5 bg-black/40 rounded-lg"><span className="text-white/70">AI draft responses</span><span className="text-green-400">Active via Claude ✓</span></div>
              </div>
            </div>
          </div>
        </Glass>
      </div>}

      {tab === "inbox" && <Glass className="overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead><tr className="border-b border-red-900/30 bg-black/40">
              <th className="text-left px-5 py-3 font-medium text-white/60 text-xs uppercase tracking-wider">Customer</th>
              <th className="text-left px-5 py-3 font-medium text-white/60 text-xs uppercase tracking-wider hidden md:table-cell">Rating</th>
              <th className="text-left px-5 py-3 font-medium text-white/60 text-xs uppercase tracking-wider">Status</th>
              <th className="text-right px-5 py-3 font-medium text-white/60 text-xs uppercase tracking-wider">Actions</th>
            </tr></thead>
            <tbody>
              {reviews.map(r => {
                const cu = cf(r.jobId);
                const jo = jf(r.jobId);
                if (!cu || !jo) return null;
                const throttled = !canSend(r.id);
                return (
                  <tr key={r.id} className="border-b border-red-900/10 hover:bg-white/5 transition">
                    <td className="px-5 py-4"><div className="font-medium">{cu.firstName} {cu.lastName}</div></td>
                    <td className="px-5 py-4 hidden md:table-cell">{r.rating > 0 ? <div className="flex gap-0.5">{Array.from({ length: 5 }).map((_, i) => <Star key={i} size={12} className={i < r.rating ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}</div> : <span className="text-white/30 text-xs">—</span>}</td>
                    <td className="px-5 py-4"><Badge tone={r.status === "completed" ? "green" : r.status === "sent" ? "yellow" : "gray"}>{r.status}</Badge></td>
                    <td className="px-5 py-4 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button onClick={() => setLandingReview(r)} title="Preview customer landing page" className="p-1.5 rounded-lg hover:bg-blue-900/30 text-white/50 hover:text-blue-400" title="Customer view"><Globe size={12} /></button>
                        <button onClick={() => { const cu2 = cf(r.jobId); if (cu2?.phone) unsubscribe(cu2.phone, "phone"); else if (cu2?.email) unsubscribe(cu2.email, "email"); }} title="Opt out of review requests" className="p-1.5 rounded-lg hover:bg-red-900/30 text-white/50 hover:text-red-400"><Ban size={12} /></button>
                        {r.status === "pending" ? <GBtn onClick={() => sendReq(r.id)} disabled={throttled} className="!text-xs !py-1 !px-2.5"><Send size={10} className="inline mr-1" />{throttled ? "Throttled" : "Send"}</GBtn> : <GBtn variant="ghost" onClick={() => setPreview(r)} className="!text-xs !py-1 !px-2.5"><Eye size={10} className="inline mr-1" />View</GBtn>}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {reviews.length === 0 && <tr><td colSpan={4} className="text-center py-10 text-white/40">Complete jobs to generate review requests</td></tr>}
            </tbody>
          </table>
        </div>
      </Glass>}

      {tab === "showcase" && <div className="space-y-4">
        <Glass className="p-4 !bg-gradient-to-br !from-yellow-950/20 !to-red-950/20 !border-yellow-700/30">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div className="flex items-center gap-2"><Trophy size={16} className="text-yellow-400" /><div><div className="font-semibold text-sm">Public Review Wall</div><div className="text-xs text-white/60">Showing reviews rated {settings.reviewShowcaseMinRating || 5}★ and above. Would embed at smocks.com/reviews.</div></div></div>
            <div className="flex items-center gap-2 text-xs">
              <span className="text-white/60">Min rating:</span>
              <GSel value={settings.reviewShowcaseMinRating || 5} onChange={e => setSettings({ ...settings, reviewShowcaseMinRating: Number(e.target.value) })} className="!py-1 !text-xs !w-auto">
                <option value={5} className="bg-black">5★</option>
                <option value={4} className="bg-black">4+★</option>
                <option value={3} className="bg-black">3+★</option>
              </GSel>
            </div>
          </div>
        </Glass>
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
          {completed.filter(r => r.rating >= (settings.reviewShowcaseMinRating || 5)).map(r => {
            const cu = cf(r.jobId);
            if (!cu) return null;
            return <Glass key={r.id} className="p-5 hover:border-yellow-500/40 transition relative overflow-hidden">
              <div className="absolute -top-4 -right-4 text-6xl opacity-10">★</div>
              <div className="flex gap-0.5 mb-3 relative">{Array.from({ length: 5 }).map((_, i) => <Star key={i} size={14} className={i < r.rating ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}</div>
              {r.feedback ? <div className="text-sm text-white/80 italic leading-relaxed mb-4 relative">"{r.feedback}"</div> : <div className="text-sm text-white/40 italic mb-4">No written feedback</div>}
              <div className="flex items-center gap-2.5 pt-3 border-t border-red-900/20">
                <div className="w-9 h-9 rounded-full bg-gradient-to-br from-red-600 to-red-900 flex items-center justify-center text-xs font-bold">{cu.firstName[0]}{cu.lastName[0]}</div>
                <div className="flex-1 min-w-0">
                  <div className="font-medium text-sm truncate">{cu.firstName} {cu.lastName[0]}.</div>
                  <div className="text-[10px] text-white/50 truncate">{cu.address?.split(",").slice(-2).join(",").trim()}</div>
                </div>
                <button onClick={() => { navigator.clipboard?.writeText("\"" + (r.feedback || "") + "\" — " + cu.firstName + " " + cu.lastName[0] + "."); toast("Review copied"); }} className="p-1.5 text-white/40 hover:text-white" title="Copy for marketing"><Copy size={12} /></button>
              </div>
            </Glass>;
          })}
          {completed.filter(r => r.rating >= (settings.reviewShowcaseMinRating || 5)).length === 0 && <div className="md:col-span-2 lg:col-span-3 text-center py-12 text-white/40">
            <Trophy size={36} className="mx-auto mb-3 opacity-30" />
            <div className="text-sm">No reviews meet the threshold yet.</div>
            <div className="text-xs mt-1">Complete jobs and collect {settings.reviewShowcaseMinRating || 5}★ ratings to fill the wall.</div>
          </div>}
        </div>
      </div>}

      <ReviewPreview review={preview} onClose={() => setPreview(null)} customer={preview ? cf(preview.jobId) : null} apiKey={settings.geminiKey} companyName={settings.companyName} onUpdate={u => preview && updRev(preview.id, u)} onSubmit={r => preview && subRev(preview.id, r)} toast={toast} />
      {landingReview && <ReviewLandingPage review={landingReview} customer={cf(landingReview.jobId)} settings={settings} onClose={() => setLandingReview(null)} onSubmit={(rating, feedback) => { updRev(landingReview.id, { rating, feedback: feedback || undefined, status: "completed" }); if (rating > 0 && rating <= 3) { const cu = cf(landingReview.jobId); setNegativeAlerts(prev => [...prev, { id: uid(), reviewId: landingReview.id, customerName: cu ? cu.firstName + " " + cu.lastName : "?", rating, at: today() }]); } }} />}
    </div>
  );
}

// ===== REVIEW LANDING PAGE (simulates /r/token URL) =====
function ReviewLandingPage({ review, customer, settings = {}, onClose, onSubmit }) {
  const [step, setStep] = useState("rate"); // rate | happy | unhappy | done
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [feedback, setFeedback] = useState("");
  const [name, setName] = useState(customer?.firstName + " " + customer?.lastName || "");
  const [submitting, setSubmitting] = useState(false);

  const companyName = settings?.companyName || "Smock's Pressure Washing";
  const googlePlaceId = settings?.googlePlaceId || "";
  const googleReviewUrl = googlePlaceId
    ? `https://search.google.com/local/writereview?placeid=${googlePlaceId}`
    : "https://g.page/r/smocks-pressure-washing/review";

  const handleRating = r => {
    setRating(r);
    setTimeout(() => { setStep(r >= 4 ? "happy" : "unhappy"); }, 350);
  };

  const handleSubmit = () => {
    setSubmitting(true);
    setTimeout(() => {
      onSubmit?.(rating, feedback);
      setStep("done");
      setSubmitting(false);
    }, 800);
  };

  if (!review || !customer) return null;

  return (
    <Modal open={true} onClose={onClose} title="" maxW="max-w-md">
      <div className="-mx-5 -mt-5">
        {/* Branded header */}
        <div className="bg-gradient-to-br from-red-600 to-red-900 px-6 py-5 text-center">
          <div className="w-14 h-14 rounded-full bg-white/10 border-2 border-white/30 flex items-center justify-center mx-auto mb-2">
            <span className="text-2xl">🚿</span>
          </div>
          <div className="font-bold text-lg text-white">{companyName}</div>
          <div className="text-red-200 text-xs">York, PA · {settings?.companyPhone || "(717) 555-0100"}</div>
        </div>

        <div className="p-6">
          {step === "rate" && (
            <div className="text-center space-y-5">
              <div>
                <div className="text-xl font-bold">Hi {customer.firstName}! 👋</div>
                <div className="text-white/60 text-sm mt-1">How was your recent service?</div>
              </div>
              <div className="flex justify-center gap-3 py-2">
                {[1,2,3,4,5].map(s => (
                  <button
                    key={s}
                    onMouseEnter={() => setHoverRating(s)}
                    onMouseLeave={() => setHoverRating(0)}
                    onClick={() => handleRating(s)}
                    className="transition-all duration-150 hover:scale-125 active:scale-95"
                  >
                    <Star
                      size={44}
                      className={"transition-colors " + (s <= (hoverRating || rating) ? "text-yellow-400 fill-yellow-400" : "text-white/20")}
                    />
                  </button>
                ))}
              </div>
              <div className="text-xs text-white/40">
                {hoverRating === 1 ? "Terrible" : hoverRating === 2 ? "Poor" : hoverRating === 3 ? "Okay" : hoverRating === 4 ? "Good" : hoverRating === 5 ? "Excellent!" : "Tap a star to rate"}
              </div>
            </div>
          )}

          {step === "happy" && (
            <div className="text-center space-y-4">
              <div className="text-4xl">🎉</div>
              <div>
                <div className="text-xl font-bold text-yellow-400">Awesome — thank you!</div>
                <div className="text-white/60 text-sm mt-1">Your {rating}-star review means the world to us. Would you mind sharing it on Google?</div>
              </div>
              <div className="flex justify-center gap-1">
                {[1,2,3,4,5].map(s => <Star key={s} size={20} className={s <= rating ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}
              </div>
              <a
                href={googleReviewUrl}
                target="_blank"
                rel="noopener noreferrer"
                onClick={() => { onSubmit?.(rating, ""); setTimeout(() => setStep("done"), 500); }}
                className="flex items-center justify-center gap-2 w-full py-3.5 bg-white text-gray-900 font-bold rounded-xl hover:bg-gray-50 transition"
              >
                <img src="https://www.google.com/images/branding/googleg/1x/googleg_standard_color_128dp.png" alt="G" className="w-5 h-5" />
                Leave a Google Review
              </a>
              <button onClick={() => { onSubmit?.(rating, "declined"); setStep("done"); }} className="text-xs text-white/40 hover:text-white/60 transition">No thanks, maybe later</button>
            </div>
          )}

          {step === "unhappy" && (
            <div className="space-y-4">
              <div className="text-center">
                <div className="text-3xl">😔</div>
                <div className="text-lg font-bold mt-2">We're sorry to hear that</div>
                <div className="text-white/60 text-sm mt-1">Please tell us what went wrong so we can make it right.</div>
              </div>
              <div className="flex justify-center gap-1">
                {[1,2,3,4,5].map(s => <Star key={s} size={18} className={s <= rating ? "text-yellow-400 fill-yellow-400" : "text-white/20"} />)}
              </div>
              <div>
                <label className="text-xs text-white/60 mb-1 block">Your feedback (private — only we see this)</label>
                <GTxt rows={4} value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="Tell us what happened and how we can improve..." />
              </div>
              <div>
                <label className="text-xs text-white/60 mb-1 block">Your name</label>
                <GInput value={name} onChange={e => setName(e.target.value)} />
              </div>
              <GBtn onClick={handleSubmit} disabled={!feedback.trim() || submitting} className="w-full !py-3">
                {submitting ? <div className="flex items-center justify-center gap-2"><div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />Submitting…</div> : "Send Private Feedback"}
              </GBtn>
              <button onClick={() => setStep("rate")} className="text-xs text-white/40 hover:text-white/60 w-full text-center transition">← Change my rating</button>
            </div>
          )}

          {step === "done" && (
            <div className="text-center py-4 space-y-3">
              <div className="text-5xl">{rating >= 4 ? "⭐" : "🙏"}</div>
              <div className="text-xl font-bold">{rating >= 4 ? "Thank you!" : "We appreciate your honesty"}</div>
              <div className="text-white/60 text-sm">
                {rating >= 4 ? "Your review helps other homeowners find us." : "We'll reach out soon to make things right."}
              </div>
              <GBtn onClick={onClose} variant="ghost" className="w-full mt-4">Close</GBtn>
              {onSubmit && <button onClick={() => onSubmit({ unsubscribe: true })} className="text-[10px] text-white/30 hover:text-white/50 underline mt-2 block w-full">Don't send me review requests — unsubscribe</button>}
            </div>
          )}
        </div>
      </div>
    </Modal>
  );
}

function ReviewPreview({ review: r, onClose, customer: c, onUpdate, onSubmit, apiKey, companyName = "Smock's", toast = () => {} }) {
  const [lr, setLr] = useState(0);
  const [lf, setLf] = useState("");
  const [aiDraft, setAiDraft] = useState("");
  const [aiLoading, setAiLoading] = useState(false);

  useEffect(() => { if (r) { setLr(r.rating || 0); setLf(r.feedback || ""); setAiDraft(""); } }, [r]);

  if (!r || !c) return null;

  const hr = n => { setLr(n); onUpdate({ rating: n }); };
  const isHappy = lr >= 4;
  const isUnhappy = lr > 0 && lr <= 3;
  const hasFeedback = (r.feedback || "").trim().length > 0 && r.status === "completed";

  const generateDraft = async () => {
    setAiLoading(true);
    try {
      const tone = r.rating >= 4 ? "warm, grateful, professional" : "sincere, apologetic, solution-focused, and professional — acknowledge the issue and offer to make it right";
      const prompt = "Draft a short reply (under 80 words) to this customer review for " + companyName + ". Tone: " + tone + ". Sign off from the owner. Review rating: " + r.rating + "/5. Customer: " + c.firstName + ". Their feedback: \"" + (r.feedback || "(no text)") + "\"\n\nReturn only the reply text, no preamble.";
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          messages: [{ role: "user", content: prompt }]
        })
      });
      if (!res.ok) throw new Error("HTTP " + res.status);
      const data = await res.json();
      const reply = (data?.content?.find(c => c.type === "text")?.text) || data?.content?.[0]?.text || "Could not generate draft.";
      setAiDraft(reply.trim());
    } catch (err) {
      setAiDraft("Error: " + (err.message || "Connection failed"));
    } finally {
      setAiLoading(false);
    }
  };

  return (
    <Modal open={!!r} onClose={onClose} title="Review" maxW="max-w-xl">
      <div className="space-y-5">
        <div className="text-center">
          <h2 className="text-xl font-bold">How did we do?</h2>
          <p className="text-sm text-white/60 mt-1">Hi {c.firstName}!</p>
        </div>
        <div className="text-center">
          <div className="flex justify-center gap-1">
            {[1, 2, 3, 4, 5].map(n => <button key={n} onClick={() => hr(n)} className="transition-transform hover:scale-125"><Star size={36} className={n <= lr ? "text-yellow-400 fill-yellow-400" : "text-white/20"} /></button>)}
          </div>
        </div>

        {isHappy && (
          <Glass className="p-4 !bg-green-950/30 !border-green-700/50 text-center">
            <div className="text-sm font-semibold text-green-300 mb-1">🎉 Share on Google?</div>
            <div className="text-xs text-white/60 mb-3">Your review helps other homeowners.</div>
            <GBtn onClick={() => window.open("https://www.google.com/search?q=smocks+pressure+washing", "_blank")} className="w-full"><ExternalLink size={12} className="inline mr-1.5" />Google Review</GBtn>
          </Glass>
        )}

        {isUnhappy && (
          <Glass className="p-4 !bg-yellow-950/30 !border-yellow-700/50">
            <div className="text-sm font-semibold text-yellow-300 mb-1">😕 We want to make it right</div>
            <div className="text-xs text-white/60">Your feedback is private. An owner will reach out within 24 hrs.</div>
          </Glass>
        )}

        <div>
          <label className="text-xs text-white/60 mb-1.5 block">{isUnhappy ? "What went wrong?" : "Tell us more (optional)"}</label>
          <GTxt rows={4} value={lf} onChange={e => { setLf(e.target.value); onUpdate({ feedback: e.target.value }); }} />
        </div>

        {/* AI Response Drafter — owner-facing, only shown for completed reviews with text */}
        {hasFeedback && <Glass className="p-4 !bg-purple-950/20 !border-purple-700/40">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2"><Bot size={14} className="text-purple-400" /><div className="text-sm font-semibold text-purple-300">Draft a response</div></div>
            <button onClick={generateDraft} disabled={aiLoading} className="text-xs text-purple-400 hover:text-purple-300 flex items-center gap-1 disabled:opacity-50">
              <Zap size={11} />{aiLoading ? "Writing..." : aiDraft ? "Regenerate" : "Generate with AI"}
            </button>
          </div>
          <div className="text-[10px] text-white/50 mb-2">Gemini drafts a reply you can post to Google / send by email. Owner-only view.</div>
          {aiDraft && <div className="space-y-2">
            <GTxt rows={5} value={aiDraft} onChange={e => setAiDraft(e.target.value)} className="!text-xs" />
            <div className="flex gap-2">
              <GBtn variant="ghost" onClick={() => { navigator.clipboard?.writeText(aiDraft); toast("Response copied"); }} className="flex-1 !text-xs"><Copy size={11} className="inline mr-1" />Copy</GBtn>
              <GBtn onClick={() => { window.open("mailto:" + c.email + "?subject=Re: Your review&body=" + encodeURIComponent(aiDraft), "_blank"); }} className="flex-1 !text-xs"><Mail size={11} className="inline mr-1" />Email</GBtn>
            </div>
          </div>}
          {!aiDraft && !aiLoading && <div className="text-[10px] text-white/50 mt-1">Click "Generate with AI" to draft a response with Claude.</div>}
        </Glass>}

        <GBtn onClick={() => { if (lr === 0) return; onSubmit(lr); }} disabled={lr === 0} className="w-full">{r.status === "completed" ? "Update" : "Submit"}</GBtn>
      </div>
    </Modal>
  );
}

